{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Validate required fields on every node
    for node in nodes:
        for field in ["id", "parent", "symbol", "depth", "removable"]:
            if field not in node:
                raise ValueError(f"Missing required field '{field}' in node")

    # Build id -> node map and parent -> [child ids] map
    node_map = {n["id"]: n for n in nodes}
    children = {n["id"]: [] for n in nodes}
    for n in nodes:
        p = n["parent"]
        if p is not None:
            if p not in node_map:
                raise ValueError(f"Parent '{p}' not found for node '{n['id']}'")
            children[p].append(n["id"])

    # Track which nodes are currently retained and per-symbol retained counts
    retained = set(n["id"] for n in nodes)
    symbol_count = {}
    for n in nodes:
        s = n["symbol"]
        symbol_count[s] = symbol_count.get(s, 0) + 1

    # Process deepest nodes first; use node ID string as stable tie-break
    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    removal_order = []

    for node in candidates:
        nid = node["id"]

        # Hard constraint: removable flag
        if not node["removable"]:
            continue

        # Hard constraint: no retained children
        if any(c in retained for c in children[nid]):
            continue

        # Hard constraint: required symbols must remain represented
        sym = node["symbol"]
        if sym in required_symbols and symbol_count.get(sym, 0) <= 1:
            continue

        # Safe to remove
        retained.discard(nid)
        symbol_count[sym] = symbol_count.get(sym, 0) - 1
        removal_order.append(nid)

    retained_sorted = sorted(retained)

    return {
        "removed_node_ids": removal_order,
        "retained_node_ids": retained_sorted
    }
"}
